        """Validate that inputs are numbers."""
        if not isinstance(a, (int, float)) or not isinstance(b, (int, float)):
            raise TypeError("Operands must be numbers")

    def _internal_add(self, a: float, b: float) -> float: return a + b
    def _internal_subtract(self, a: float, b: float) -> float: return a - b
    def _internal_multiply(self, a: float, b: float) -> float: return a * b
    def _internal_divide(self, a: float, b: float) -> float:
        if b == 0: raise ValueError("Cannot divide by zero.")
        return a / b
    def _internal_power(self, base: float, exponent: float) -> float:
        res = pow(base, exponent)
        if isinstance(res, complex): raise ValueError("Result is complex.")
        return float(res)
    def _internal_modulo(self, a: float, b: float) -> float:
        if b == 0: raise ValueError("Cannot perform modulo by zero.")
        return a % b

    def add(self, a: float, b: float) -> float:
        self._validate_inputs(a, b)
        res = self._internal_add(a, b)
        self._record("add", a, b, res)
        return res

    def subtract(self, a: float, b: float) -> float:
        self._validate_inputs(a, b)
        res = self._internal_subtract(a, b)
        self._record("subtract", a, b, res)
        return res

    def multiply(self, a: float, b: float) -> float:
        self._validate_inputs(a, b)
        res = self._internal_multiply(a, b)
        self._record("multiply", a, b, res)
        return res

    def divide(self, a: float, b: float) -> float:
        self._validate_inputs(a, b)
        res = self._internal_divide(a, b)
        self._record("divide", a, b, res)
        return res

    def power(self, base: float, exponent: float) -> float:
        self._validate_inputs(base, exponent)
        res = self._internal_power(base, exponent)
        self._record("power", base, exponent, res)
        return res

    def modulo(self, a: float, b: float) -> float:
        self._validate_inputs(a, b)
        res = self._internal_modulo(a, b)
        self._record("modulo", a, b, res)
        return res

    def memory_store(self, value: float) -> None:
        if not isinstance(value, (int, float)):
            raise TypeError("Memory value must be a number.")
        self._memory = float(value)
        self._record("memory_store", value, math.nan, float(value))

    def memory_recall(self) -> float:
        if self._memory is None:
            raise ValueError("Memory is empty.")
        return self._memory

    def memory_clear(self) -> None:
        self._memory = None
        self._record("memory_clear", math.nan, math.nan, 0.0)

    def get_history(self) -> list[HistoryEntry]:
        return self._history.copy()

    def clear_history(self) -> None:
