        allowed_operators = {
            ast.Add: self._internal_add,
            ast.Sub: self._internal_subtract,
            ast.Mult: self._internal_multiply,
            ast.Div: self._internal_divide,
            ast.Pow: self._internal_power,
            ast.Mod: self._internal_modulo
        }

        def _eval(node: Any) -> float:
