        allowed_nodes = (ast.Constant, ast.BinOp, ast.UnaryOp, ast.Add, ast.Sub, 
                         ast.Mult, ast.Div, ast.Pow, ast.Mod, ast.USub, ast.UAdd)

        def _eval(node: Any) -> float:
            if isinstance(node, ast.Constant):
                if not isinstance(node.value, (int, float)):
                    raise TypeError("Only numbers allowed in expressions.")
                return float(node.value)
            elif isinstance(node, ast.BinOp):
                left, right = _eval(node.left), _eval(node.right)
                op = node.op
                if isinstance(op, ast.Add): return self._internal_add(left, right)
                if isinstance(op, ast.Sub): return self._internal_subtract(left, right)
                if isinstance(op, ast.Mult): return self._internal_multiply(left, right)
                if isinstance(op, ast.Div): return self._internal_divide(left, right)
                if isinstance(op, ast.Pow): return self._internal_power(left, right)
                if isinstance(op, ast.Mod): return self._internal_modulo(left, right)
            elif isinstance(node, ast.UnaryOp):
                operand = _eval(node.operand)
                if isinstance(node.op, ast.USub): return -operand
                if isinstance(node.op, ast.UAdd): return operand
            raise TypeError(f"Unsupported expression component: {type(node).__name__}")

        try:
            tree = ast.parse(expression, mode='eval')
            result = _eval(tree.body)
            self._record("evaluate", None, None, result, expression)
            return result
        except (SyntaxError, TypeError, ZeroDivisionError, CalculatorError) as e:
            raise CalculatorError(f"Evaluation failed: {e}")
